import express from 'express';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import { initializeApp, getApps, getApp } from 'firebase/app';
import { getFirestore, collection, getDocs, addDoc, updateDoc, deleteDoc, doc, getDoc, setDoc } from 'firebase/firestore';

// Carrega as variáveis do ambiente de desenvolvimento ou Cloud Run
const firebaseConfig = {
  apiKey: process.env.VITE_FIREBASE_API_KEY,
  authDomain: process.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: process.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.VITE_FIREBASE_APP_ID
};

const isConfigured = !!firebaseConfig.apiKey && firebaseConfig.apiKey !== 'SUA_API_KEY_AQUI';
const firebaseApp = isConfigured
  ? (!getApps().length ? initializeApp(firebaseConfig) : getApp())
  : null;
const db = firebaseApp ? getFirestore(firebaseApp) : null;

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // Middleware de CORS robusto para aceitar requisições do seu GitHub Pages e do ambiente de preview
  app.use((req, res, next) => {
    const allowedOrigins = [
      'https://jeffmr.github.io',
      'http://localhost:3000',
    ];
    const origin = req.headers.origin;
    if (origin) {
      if (allowedOrigins.includes(origin) || origin.endsWith('.run.app') || origin.includes('localhost') || origin.includes('127.0.0.1')) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Credentials', 'true');
      }
    } else {
      res.setHeader('Access-Control-Allow-Origin', '*');
    }
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    if (req.method === 'OPTIONS') {
      return res.sendStatus(200);
    }
    next();
  });

  // Fallbacks de dados para manter a aplicação 100% operacional caso o banco de dados não esteja pronto
  let mockProjects = [
    {
      id: '1',
      title: 'E-commerce Platform',
      description: 'Plataforma completa de e-commerce com carrinho de compras, integração de pagamentos e painel administrativo.',
      technologies: ['React', 'Node.js', 'PostgreSQL'],
      link: 'https://github.com/jeffmr',
      createdAt: Date.now()
    },
    {
      id: '2',
      title: 'API de Gerenciamento',
      description: 'API RESTful escalável para gerenciamento de recursos, autenticação JWT e arquitetura limpa.',
      technologies: ['Express', 'TypeScript', 'MongoDB'],
      link: 'https://github.com/jeffmr',
      createdAt: Date.now() - 100000
    }
  ];

  let mockProfile = {
    name: 'Jefferson Miranda',
    username: 'jeffmr',
    bio: 'Desenvolvedor Fullstack focado em criar soluções web modernas, escaláveis e responsivas. Especialista em ecossistemas JavaScript (Node.js e React).',
    role: 'Desenvolvedor Fullstack | Node.js | React',
    links: [
      { id: '1', platform: 'GitHub', url: 'https://github.com/jeffmr' },
      { id: '2', platform: 'LinkedIn', url: 'https://linkedin.com/in/jeffmr' },
      { id: '3', platform: 'Email', url: 'mailto:contatejeff@gmail.com' }
    ],
    skills: [
      { id: '1', name: 'React.js', level: 'Avançado', category: 'Frontend' },
      { id: '2', name: 'Node.js', level: 'Avançado', category: 'Backend' },
      { id: '3', name: 'TypeScript', level: 'Avançado', category: 'Fullstack' },
      { id: '4', name: 'Tailwind CSS', level: 'Avançado', category: 'Frontend' },
      { id: '5', name: 'PostgreSQL', level: 'Intermediário', category: 'Banco de Dados' }
    ],
    experiences: [
      {
        id: '1',
        role: 'Desenvolvedor Fullstack Sênior',
        company: 'Tech Solutions Inc.',
        period: '2023 - Presente',
        description: 'Liderança técnica no desenvolvimento de plataformas web escaláveis utilizando React e Node.js. Implementação de arquiteturas em microsserviços e integração contínua.'
      },
      {
        id: '2',
        role: 'Desenvolvedor Frontend',
        company: 'Agência Digital Criativa',
        period: '2021 - 2023',
        description: 'Criação de interfaces ricas e responsivas. Otimização de performance web e estruturação de design systems com Tailwind CSS e Framer Motion.'
      }
    ]
  };

  // --- API ENDPOINTS ---

  // Fornecer a config publica do Firebase dinamicamente para o front-end (ex: autenticação)
  app.get('/api/config', (req, res) => {
    res.json({
      apiKey: process.env.VITE_FIREBASE_API_KEY || '',
      authDomain: process.env.VITE_FIREBASE_AUTH_DOMAIN || '',
      projectId: process.env.VITE_FIREBASE_PROJECT_ID || '',
      storageBucket: process.env.VITE_FIREBASE_STORAGE_BUCKET || '',
      messagingSenderId: process.env.VITE_FIREBASE_MESSAGING_SENDER_ID || '',
      appId: process.env.VITE_FIREBASE_APP_ID || ''
    });
  });

  // Projetos
  app.get('/api/projects', async (req, res) => {
    if (!db) {
      return res.json(mockProjects);
    }
    try {
      const querySnapshot = await getDocs(collection(db, 'projects'));
      const projects = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      res.json(projects);
    } catch (error) {
      console.error('Erro ao buscar projetos:', error);
      res.json(mockProjects);
    }
  });

  app.post('/api/projects', async (req, res) => {
    const projectData = req.body;
    if (!db) {
      const newProj = { ...projectData, id: String(Date.now()), createdAt: Date.now() };
      mockProjects.push(newProj);
      return res.json(newProj);
    }
    try {
      const docRef = await addDoc(collection(db, 'projects'), {
        ...projectData,
        createdAt: projectData.createdAt || Date.now()
      });
      res.json({ id: docRef.id, ...projectData });
    } catch (error: any) {
      console.error('Erro ao salvar projeto:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.put('/api/projects/:id', async (req, res) => {
    const { id } = req.params;
    const projectData = req.body;
    if (!db) {
      mockProjects = mockProjects.map(p => p.id === id ? { ...p, ...projectData } : p);
      return res.sendStatus(200);
    }
    try {
      const docRef = doc(db, 'projects', id);
      await updateDoc(docRef, projectData);
      res.sendStatus(200);
    } catch (error: any) {
      console.error('Erro ao atualizar projeto:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.delete('/api/projects/:id', async (req, res) => {
    const { id } = req.params;
    if (!db) {
      mockProjects = mockProjects.filter(p => p.id !== id);
      return res.sendStatus(200);
    }
    try {
      const docRef = doc(db, 'projects', id);
      await deleteDoc(docRef);
      res.sendStatus(200);
    } catch (error: any) {
      console.error('Erro ao deletar projeto:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Perfil
  app.get('/api/profile', async (req, res) => {
    if (!db) {
      return res.json(mockProfile);
    }
    try {
      const docRef = doc(db, 'profiles', 'main_profile');
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        return res.json(docSnap.data());
      }
      res.json(mockProfile);
    } catch (error) {
      console.error('Erro ao obter perfil:', error);
      res.json(mockProfile);
    }
  });

  app.post('/api/profile', async (req, res) => {
    const profileData = req.body;
    if (!db) {
      mockProfile = { ...mockProfile, ...profileData };
      return res.sendStatus(200);
    }
    try {
      const docRef = doc(db, 'profiles', 'main_profile');
      await setDoc(docRef, profileData, { merge: true });
      res.sendStatus(200);
    } catch (error: any) {
      console.error('Erro ao atualizar perfil:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Servir ativos do Vite em desenvolvimento, ou build estático em produção
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`[Fullstack Server] rodando com sucesso na porta ${PORT}`);
  });
}

startServer();
